<script setup lang="ts">import{regexTemplates}from'../../data/regexTemplates';import{useRenameStore}from'../../stores/rename';defineProps<{modelValue:boolean}>();const emit=defineEmits(['update:modelValue']);const s=useRenameStore();function apply(t:typeof regexTemplates[number]){s.useRegex=true;s.setSearch(t.search);s.setReplacement(t.replacement);s.renameExtension=t.renameExtension;emit('update:modelValue',false)}</script><template><el-drawer :model-value="modelValue" title="正则模板" size="430" @close="$emit('update:modelValue',false)"><p class="intro">不需要理解正则语法。查看前后示例，选择符合目的的模板即可一键填入。</p><div class="templates"><article v-for="t in regexTemplates" :key="t.title"><small>{{t.category}}</small><h3>{{t.title}}</h3><p>{{t.purpose}}</p><code>{{t.before}} → {{t.after}}</code><el-button type="primary" plain @click="apply(t)">应用模板</el-button></article></div></el-drawer></template><style scoped>.intro{color:var(--muted);line-height:1.7}.templates{display:grid;gap:12px}article{display:grid;gap:7px;padding:15px;border:1px solid var(--border);border-radius:var(--radius)}h3,p{margin:0}small{color:var(--primary)}code{padding:8px;background:var(--surface-soft);border-radius:7px;overflow:hidden;text-overflow:ellipsis}.el-button{justify-self:end}</style>
